"""AQS-BOM-SC-001 rev G section 6: reconcile the self-copy matrix with the unit BOMs (X-PRO-04, A-M-206). Every PLANT_BOM line
(AQS-PRO-001) is classed by its stated material against the elements the graph actually recovers (present-edge species). The worst
constituent of a multi-material line sets its flag. Writes docs-authority/inventory/SELF_COPY_RECON.csv and rewrites section 6."""
import csv, json, os, re, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
g = json.load(open('flow_graph/plant_flow_graph.json')); SP = set()
for e in g['edges']:
    if e['presence'] == 'present': SP |= set((e.get('composition') or {}).keys())
RANK = {'Closed': 0, 'Partial': 1, 'Missing': 2, 'Unstated': 3}
# (regex, flag, making path, gap). Element availability is tested against SP so the flags move with the graph.
def M(el): return 'Closed' if el in SP else 'Missing'
RULES = [(r'PVDF|PTFE|FKM|fluoro', 'Missing', '-', 'no fluorine source on site; end of life Q-011'),
 (r'316|304|310S|stainless|SA-182|SA-240|SA-312|A312|Hastelloy|Incoloy|Inconel|NiCr', M('Cr'), 'MET_MELT + forming', 'needs Cr (and Mo for 316L); Cr/Mo not recovered by the leach/EW train' if 'Cr' not in SP else ''),
 (r'titanium', M('Ti'), 'MET_MELT', 'Ti not recovered (ilmenite route not in the graph)' if 'Ti' not in SP else ''),
 (r'Pt-Rh|platinum', 'Missing', '-', 'Pt and Rh not recovered (Au, Ag are)'),
 (r'bought', 'Missing', '-', 'line says bought: no on-site path stated'),
 (r'Al2O3', 'Partial', 'leach Al2O3 -> ceramic fibre', 'Al stays in the leach liquor as solute; alumina recovery is a study'),
 (r'IEC 63 frame|motor', 'Partial', 'Fe/Cu (MET) + FAB for drives', 'electrical steel and magnet wire enamel are studies'),
 (r'mica', 'Missing', '-', 'no mica source; substitute glass-mica from GLASS is a study'),
 (r'[Bb]orosilicate', 'Partial', 'GLASS', 'boron not recovered; soda-lime or high-silica glass from GLASS is the substitute study'),
 (r'HDPE|PE100|PE4710|PP-H|\bPP\b|polypropylene|polyethylene', 'Partial', 'OIL cuts -> olefin -> polymer (MFG)', 'olefin cracking and polymerisation are not yet units in the graph'),
 (r'CPVC|PVC', 'Partial', 'OIL cuts + Cl2/HCl (WET) -> PVC (MFG)', 'Cl on site; ethylene and VCM steps not yet units'),
 (r'FRP|vinyl ester', 'Partial', 'GLASS fibre + resin', 'glass fibre from GLASS; vinyl ester resin route is a study'),
 (r'EPDM|silicone|PIR|polystyrene|DVB', 'Partial', 'OIL/MEOH chemistry', 'monomer route not yet in the graph'),
 (r'graphite', 'Partial', 'OIL_PYRO char', 'graphitisation above 2,500 C not in the heat ladder'),
 (r'(?i)refractory|mineral wool|C547|glass', 'Closed', 'GLASS / silicate melt', ''),
 (r'(?i)carbon steel|\bCS\b|A106|SA-106|SA-105|steel', M('Fe'), 'Fe EW -> MET_MELT -> mill/draw', ''),
 (r'\bCu\b|copper', M('Cu'), 'Cu EW -> WIRE_DRAW', ''), (r'[Nn]ickel', M('Ni'), 'Ni EW -> MET_MELT', '')]
rows = []
for r in csv.DictReader(open('docs-authority/inventory/PLANT_BOM.csv')):
    m = r['material']; hits = [(f, p, gp, rx) for rx, f, p, gp in RULES if re.search(rx, m)]
    if not hits: f, p, gp, rx = 'Unstated', '-', 'material not stated on the unit BOM line' if not m.strip() or 'no duty sheet' in m or 'see basis' in m or 'No wetted' in m else f'not classed: {m[:40]}', ''
    else: f, p, gp, rx = max(hits, key=lambda h: RANK[h[0]])
    rows.append(dict(unit=r['unit'], item=r['item'][:80], qty=r['qty'], material=m[:80], flag=f, making_path=p, gap=gp))
with open('docs-authority/inventory/SELF_COPY_RECON.csv', 'w', newline='') as fo:
    w = csv.DictWriter(fo, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
K = collections.Counter(r['flag'] for r in rows); G = collections.Counter((r['flag'], r['gap']) for r in rows if r['flag'] != 'Closed')
sec = ['<!-- X-PRO-04 BEGIN -->', '## 7. Reconciliation with the unit BOMs (rev G, X-PRO-04, A-M-206)', '',
       f"Generated by `docs-authority/_sc_reconcile.py` from AQS-PRO-001 ({len(rows)} lines) against the species on present graph edges. Per line: `docs-authority/inventory/SELF_COPY_RECON.csv`.", '',
       '| Flag | BOM lines |', '|---|---|'] + [f'| {k} | {K[k]} |' for k in RANK] + ['', '| Flag | Gap | Lines |', '|---|---|---|'] + [f'| {f} | {gp} | {n} |' for (f, gp), n in sorted(G.items(), key=lambda x: (-RANK[x[0][0]], -x[1]))]
sec += ['', 'Result: the section 3 matrix rows "Structural metal stock" and "Wire / mill / melt" hold for carbon steel, Cu and Ni, but not for the stainless and titanium lines, which need Cr, Mo and Ti that the graph does not recover. Those rows, and every fluoropolymer line, are Missing until an on-site route or a substitute material is designed. `reprap_bom_complete` is therefore false at rev G.', '<!-- X-PRO-04 END -->']
s = open('docs-authority/SELF_COPY_BOM.md').read()
s = re.sub(r'<!-- X-PRO-04 BEGIN -->.*?<!-- X-PRO-04 END -->', '\n'.join(sec), s, flags=re.S) if 'X-PRO-04 BEGIN' in s else s.rstrip() + '\n\n' + '\n'.join(sec) + '\n'
s = s.replace('Revision: F  ', 'Revision: G  ', 1).replace('| F | 5 |', '| G | 6 | Section 6: reconciliation with the unit BOMs (X-PRO-04); `reprap_bom_complete` false: Cr, Mo, Ti, F not recovered | 2026-10-16 |\n| F | 5 |', 1) if 'Revision: F  ' in s else s
open('docs-authority/SELF_COPY_BOM.md', 'w').write(s); print(K, len(G))
# propagate the C4 flag: false while any line is Missing (rev G)
flag = K['Missing'] == 0; note = f"AQS-BOM-SC-001 Rev G. Reconciled with the unit BOMs (X-PRO-04): {K['Missing']} lines Missing (Cr, Mo, Ti, F not recovered), so reprap_bom_complete is {str(flag).lower()}. On-site flags stay false."
for p in ('flow_graph/plant_flow_graph.json', 'design_tool/aqs_design_tool/data/candidate_mvs.json'):
    t = open(p).read(); t2 = re.sub(r'"reprap_bom_complete": (true|false)', f'"reprap_bom_complete": {str(flag).lower()}', t)
    t2 = t2.replace('"AQS-BOM-SC-001 Rev F. The matrix warrants reprap_bom_complete. On-site flags stay false. Present CAD is not in this session."', json.dumps(note))
    t2 = re.sub(r'"AQS-BOM-SC-001 Rev G\. Reconciled[^"]*"', json.dumps(note), t2)
    if t2 != t: open(p, 'w').write(t2)
